const g=(a,t)=>a==="Academy"?[{title:"User Guide",results:t.filter(e=>e.pageType!=="Page")},{title:"Landing Pages",results:t.filter(e=>e.pageType==="Page")}]:a==="Templates"?[{title:"Templates",results:t}]:a==="Blog"?[{title:"Blog",results:t}]:a==="Help Center"?[{title:"User Guide",results:t.filter(e=>e.pageType!=="Page"&&e.pageType!=="TemplatePage")},{title:"Landing Pages",results:t.filter(e=>e.pageType==="Page")},{title:"Templates",results:t.filter(e=>e.pageType==="TemplatePage")},{title:"Blog",results:t.filter(e=>e.pageType==="BlogPage")}]:[];export{g};
